package com.indianservers.krishna4u.feature.oneminute

data class OneMinuteKrishnaStory(
    val number: Int,
    val id: String,
    val theme: String,
    val title: String,
    val story: String,
    val moral: String,
    val action: String
)

private fun story(number: Int, theme: String, title: String, text: String, moral: String, action: String) =
    OneMinuteKrishnaStory(number, "story-$number", theme, title, text, moral, action)

val oneMinuteKrishnaStories = listOf(
    story(1, "Beginnings", "Light in the Prison", "Krishna was born while Devaki and Vasudeva were imprisoned by fear and power. Yet hope entered the darkest room without asking darkness for permission.", "A difficult beginning cannot imprison your purpose.", "Bring one hopeful action into a difficult situation today."),
    story(2, "Beginnings", "The Basket Through the Storm", "Vasudeva carried infant Krishna through rain and danger, protecting the life entrusted to him. He could not control the storm, but he could keep taking the next careful step.", "Responsibility moves even when certainty is absent.", "Complete the next safe step in a duty you have delayed."),
    story(3, "Beginnings", "The River Makes a Way", "As Vasudeva crossed the Yamuna, the journey seemed impossible. The story remembers nature itself making room for a sincere mission of protection.", "A worthy path often opens after courage begins walking.", "Start one meaningful task before you feel completely ready."),
    story(4, "Beginnings", "Two Families, One Love", "Devaki gave Krishna life; Yashoda filled his childhood with daily care. Krishna’s story honours both sacrifice and the love that wakes, feeds, protects and stays.", "Family is revealed through loving responsibility.", "Thank a parent, guardian or caregiver for one specific sacrifice."),
    story(5, "Beginnings", "The Universe in a Child", "When Yashoda looked into Krishna’s mouth, tradition says she glimpsed the universe. The child she corrected every day also carried a mystery beyond her understanding.", "Never assume you have understood another soul completely.", "Meet one familiar person with fresh curiosity today."),
    story(6, "Beginnings", "The Butter Pot", "Krishna’s butter adventures filled Gokul with laughter and exasperation. Behind the playful story is a reminder that affection can soften a home without removing the need for loving boundaries.", "Joy and discipline can live in the same family.", "Create one playful moment without neglecting your responsibility."),
    story(7, "Beginnings", "The Rope That Stayed Short", "Yashoda tried to tie little Krishna safely, but every rope seemed too short until effort was joined by love. The story turns correction into a lesson about patient care.", "Love makes discipline protective rather than humiliating.", "Correct one mistake calmly, without attacking the person."),
    story(8, "Beginnings", "The Fruit Vendor’s Handful", "A fruit vendor accepted the few grains little Krishna could carry and gave generously. What looked like an uneven exchange became a celebration of the heart behind an offering.", "Sincerity gives small gifts great value.", "Share something useful without expecting repayment."),
    story(9, "Beginnings", "Dust on Krishna’s Feet", "Krishna returned from grazing the calves with dust on his feet and happiness on his face. Divine dignity did not prevent him from joining ordinary work and friendship.", "No honest duty is beneath a great soul.", "Do one ordinary household task with full attention."),

    story(10, "Courage", "The Poison Hidden in Kindness", "Putana arrived disguised as care while carrying danger. Krishna’s story teaches young hearts that appearances can mislead and that trusted protection matters.", "Kindness is proven by conduct, not appearance alone.", "Tell a trusted adult about any behaviour that makes you feel unsafe."),
    story(11, "Courage", "The Cart That Seemed Too Heavy", "A threatening cart towered over infant Krishna, yet the danger was overturned. The episode reminds us that problems can look larger than the strength waiting to awaken.", "Do not measure your courage only by the size of the obstacle.", "Break one intimidating problem into its smallest part."),
    story(12, "Courage", "The Whirlwind of Confusion", "Trinavarta carried Krishna into a violent whirlwind where nothing felt stable. The storm lost its power when Krishna remained centred.", "A centred mind is harder for confusion to carry away.", "Plant both feet, breathe slowly and name what is true."),
    story(13, "Courage", "Krishna and Kaliya", "The Yamuna had become dangerous under Kaliya’s poison. Krishna confronted the threat, stopped its harm and restored safety to the water and community.", "Courage protects life; it does not perform for applause.", "Safely report one danger others may be ignoring."),
    story(14, "Courage", "Dancing Above Poison", "The image of Krishna dancing on Kaliya turns fear into disciplined balance. He did not become poisonous in order to overcome poison.", "Do not copy the harmful behaviour you are resisting.", "Answer one harsh moment without becoming harsh yourself."),
    story(15, "Courage", "The Forest Fire", "When fire surrounded the cowherd children, panic could not show them a path. They turned together toward Krishna and were led beyond fear.", "In crisis, seek help instead of hiding danger.", "Learn one emergency number or safety procedure today."),
    story(16, "Courage", "The Hill Held High", "Krishna lifted Govardhan so the community, animals and land could shelter together from the storm. His strength created safety rather than status.", "The strongest person makes room for others beneath their protection.", "Use one ability or privilege to help someone vulnerable."),
    story(17, "Courage", "Seven Days Together", "Krishna held Govardhan, but the people remained gathered beneath it, supporting one another through the long rain. Protection became a community practice.", "Endurance grows when burdens are shared.", "Ask one struggling person what practical help would lighten today."),
    story(18, "Courage", "Indra Learns Humility", "Indra’s wounded pride became a storm, but the storm did not make him greater. When he recognised his mistake, humility restored wisdom.", "Power without humility can harm those it should serve.", "Admit one mistake without adding an excuse."),

    story(19, "Friendship", "Sudama’s Small Gift", "Sudama brought Krishna a humble handful of flattened rice, embarrassed by its simplicity. Krishna received it with the delight reserved for love, not luxury.", "A true friend measures affection, not price.", "Give a thoughtful, simple gift or message to a friend."),
    story(20, "Friendship", "Krishna Leaves the Throne", "When Sudama arrived, Krishna did not make an old friend wait beneath royal status. He welcomed him personally and remembered their shared life.", "Success should not make old relationships feel small.", "Contact a friend who knew you before your achievements."),
    story(21, "Friendship", "Sudama Was Not Shamed", "Krishna saw Sudama’s poverty but did not turn friendship into a public display of charity. He protected his friend’s dignity while responding with care.", "Help should restore dignity, not advertise the helper.", "Offer support privately and ask what is actually needed."),
    story(22, "Friendship", "The Choice Before Arjuna", "Arjuna could choose Krishna’s vast army or Krishna himself without weapons. He chose presence, counsel and trust over impressive numbers.", "The right guide can matter more than the largest advantage.", "Choose advice from the wisest person, not the loudest crowd."),
    story(23, "Friendship", "The Charioteer’s Seat", "Krishna accepted the role of Arjuna’s charioteer. He guided the horses, listened to Arjuna’s crisis and served without needing the warrior’s glory.", "True friendship is willing to serve without taking over.", "Ask a friend whether they need listening, advice or practical help."),
    story(24, "Friendship", "The Bow That Was Lowered", "When Arjuna lowered his bow in confusion, Krishna did not mock him for weakness. Their deepest conversation began because distress was allowed to speak.", "A safe friend makes honesty possible.", "Listen to someone’s struggle before offering solutions."),
    story(25, "Friendship", "Draupadi Calls for Help", "In a moment of humiliation, Draupadi refused to accept injustice as normal. Her call for protection reminds every friend to stand beside dignity when others remain silent.", "Friendship becomes sacred when it refuses to abandon the vulnerable.", "Safely interrupt exclusion or seek responsible help."),
    story(26, "Friendship", "Uddhava’s Questions", "Uddhava’s friendship with Krishna made room for difficult spiritual questions. Their bond was not threatened by sincere inquiry.", "Strong relationships welcome thoughtful questions.", "Ask someone you trust one question you have been hiding."),
    story(27, "Friendship", "Lunch in the Pasture", "Krishna sat among the cowherd children and shared an ordinary meal. Nobody needed a throne for the moment to become precious.", "Presence can make simple time unforgettable.", "Share a screen-free meal with someone today."),

    story(28, "Nature & Care", "Every Cow Had a Name", "Tradition remembers Krishna knowing and caring for the cows individually. Attention turned responsibility into relationship.", "Care begins when we stop treating living beings as numbers.", "Notice and meet one specific need of an animal or dependent."),
    story(29, "Nature & Care", "The Peacock’s Feather", "Krishna wore a peacock feather rather than a heavy symbol of conquest. Beauty from nature became a sign of joy and harmony.", "What we admire in nature, we should also protect.", "Spend ten minutes outdoors and leave no waste behind."),
    story(30, "Nature & Care", "The Flute’s Hollow Centre", "A flute makes music because it is open enough for breath to pass through it. In Krishna’s hands, emptiness became melody.", "Letting go of ego creates room for a larger purpose.", "Enter one conversation ready to listen rather than impress."),
    story(31, "Nature & Care", "The River Needed Healing", "Kaliya’s poison made the Yamuna unsafe for animals and families. Krishna’s response connected spiritual courage with restoring the environment.", "Protecting nature is part of protecting people.", "Reduce one source of water waste or pollution today."),
    story(32, "Nature & Care", "Govardhan Was Not Just a Hill", "Krishna pointed to the hill, forests, cows and workers who sustained village life. Gratitude moved from distant display toward the living world nearby.", "Respect the sources that quietly support your life.", "Thank or help someone whose work usually goes unnoticed."),
    story(33, "Nature & Care", "Shelter for Every Creature", "Under Govardhan, people and animals received shelter together. Safety was not reserved only for the powerful or useful.", "Compassion widens the circle of protection.", "Place clean water safely for birds or animals where appropriate."),
    story(34, "Nature & Care", "The Shade of Vrindavan", "Krishna’s childhood unfolded among trees, riverbanks and pastures. Nature was not background decoration; it was home, teacher and shared inheritance.", "Belonging to nature creates responsibility toward it.", "Care for one tree or plant consistently this week."),
    story(35, "Nature & Care", "A Leaf Offered with Love", "Krishna teaches that a leaf, flower, fruit or water offered sincerely is received. Devotion does not require wasteful display.", "Love, not expense, makes an offering sacred.", "Offer something simple with gratitude and avoid unnecessary waste."),
    story(36, "Nature & Care", "Every Grain Has a Journey", "A meal reaches us through soil, rain, animals, transport and human labour. Remembering Krishna before eating turns consumption into gratitude.", "Food deserves respect because many lives support it.", "Take only what you can finish and share safe leftovers."),

    story(37, "Dharma", "Kamsa’s Fearful Crown", "Kamsa tried to preserve power by harming anyone he feared. The more tightly he held the crown, the more fear ruled him.", "Power protected through injustice becomes its own prison.", "Do not harm another person merely to protect your status."),
    story(38, "Dharma", "The Throne Returned", "After Kamsa’s fall, Krishna restored Ugrasena rather than claiming the throne for himself. Victory did not become an excuse for personal ambition.", "Dharma restores rightful responsibility instead of collecting power.", "Return credit or authority to the person who earned it."),
    story(39, "Dharma", "Leaving Beloved Mathura", "Krishna moved his people toward Dwarka when repeated attacks made Mathura unsafe. He accepted misunderstanding in order to protect lives.", "Courage sometimes retreats from pride to preserve what matters.", "Change one plan when safety or wellbeing clearly requires it."),
    story(40, "Dharma", "A City Built for Safety", "Dwarka represented foresight: a secure home prepared before another crisis arrived. Krishna joined courage with planning.", "Good intentions need thoughtful preparation.", "Write one risk and one backup plan for an important goal."),
    story(41, "Dharma", "The Peace Messenger", "Before war, Krishna carried a proposal for peace to the Kaurava court. He sought a just settlement without pretending injustice did not exist.", "Try sincere dialogue before conflict, but do not call surrendering justice peace.", "Begin one difficult conversation with a fair, specific proposal."),
    story(42, "Dharma", "The Army and the Guide", "Krishna allowed Duryodhana and Arjuna to choose freely between his army and his counsel. Their choices revealed what each trusted most.", "Decisions reveal values before results reveal success.", "Ask what value your next major choice will strengthen."),
    story(43, "Dharma", "Patience with a Boundary", "Krishna endured Shishupala’s repeated hostility for a long time, but patience did not mean endless permission. The story joins forgiveness with accountability.", "Compassion needs boundaries when harm keeps repeating.", "State one boundary calmly and explain the consequence."),
    story(44, "Dharma", "The Syamantaka Rumour", "When accused in the mystery of the Syamantaka jewel, Krishna followed evidence instead of answering gossip with gossip. Truth was restored through patient investigation.", "Facts protect dignity better than angry rumours.", "Separate what you know from what you assume before speaking."),
    story(45, "Dharma", "Service at the Rajasuya", "At a grand royal gathering, Krishna accepted humble service rather than demanding the most visible honour. Leadership was expressed through usefulness.", "No necessary task is too small for a true leader.", "Choose the least celebrated helpful task and do it well."),

    story(46, "Mind", "Arjuna Names His Distress", "Arjuna described his trembling, sorrow and confusion instead of hiding behind false confidence. Naming the experience made guidance possible.", "An emotion becomes easier to guide when it is honestly named.", "Complete: “I notice I feel ___ because ___ matters to me.”"),
    story(47, "Mind", "The Steady Lamp", "Krishna compares a disciplined mind to a lamp protected from wind. The flame is not forced; the conditions around it are cared for.", "Focus grows when your environment supports it.", "Remove one distraction before your next study period."),
    story(48, "Mind", "Bring It Back Again", "Arjuna says the mind is restless. Krishna agrees, then teaches practice and detachment rather than shame.", "Mindfulness is the patient art of returning.", "For three minutes, return attention to your breath whenever it wanders."),
    story(49, "Mind", "Friend or Enemy Within", "Krishna teaches that a trained mind can become a friend, while an uncontrolled mind can work against us. The same energy changes through practice.", "Self-mastery turns inner power into an ally.", "Keep one small promise to yourself today."),
    story(50, "Mind", "The Turtle’s Wisdom", "The Gita describes a turtle drawing in its limbs when danger approaches. Wise restraint knows when not to follow every attractive impulse.", "You do not have to obey every urge.", "Delay one unnecessary impulse for ten minutes."),
    story(51, "Mind", "The Ocean Receives Rivers", "Rivers enter the ocean, yet it remains within its shores. Krishna uses this image for a person who can receive desires without being carried away by each one.", "Peace is spacious enough to hold desire without serving it.", "Notice one desire and ask whether acting on it serves your values."),
    story(52, "Mind", "The Chain from Thought to Anger", "Krishna traces how repeated attention can become attachment, frustrated desire, anger and confused judgment. Awareness can interrupt the chain early.", "Guard attention before anger needs to be controlled.", "Move your attention away from one trigger that you keep feeding."),
    story(53, "Mind", "Balanced Food and Sleep", "Krishna tells Arjuna that discipline does not grow through extremes of eating, sleeping, work or recreation. Balance supports meditation.", "A steady life supports a steady mind.", "Choose a realistic bedtime or balanced meal today."),
    story(54, "Mind", "Pause Before the Arrow", "The Gita’s conversation happens before Arjuna acts. The pause is not cowardice; it is where emotion, duty and consequence are examined.", "A wise pause protects action from impulse.", "Take three breaths before your next difficult reply."),

    story(55, "Action", "Your Right Is to the Work", "Krishna reminds Arjuna that effort and intention are his responsibility, while the final result depends on more than one person. This frees action from paralysis.", "Own your effort without claiming control of every outcome.", "Give twenty focused minutes to the work in front of you."),
    story(56, "Action", "Your Own Path", "Krishna teaches that one’s own duty, even imperfectly performed, is safer than copying another person’s path. Imitation can hide our real responsibility.", "Purpose grows through honest duty, not comparison.", "Take one step on your goal without checking another person’s progress."),
    story(57, "Action", "Work as an Offering", "Krishna asks that action be offered rather than possessed by ego. The same task changes when service replaces recognition.", "Sincerity can make ordinary work sacred.", "Dedicate one task to someone’s wellbeing before beginning."),
    story(58, "Action", "The Leader Goes First", "Krishna explains that people follow the standards leaders embody. Instruction without example has little strength.", "Your conduct teaches before your words do.", "Model the behaviour you want from your group."),
    story(59, "Action", "The Lotus and the Water", "The Gita compares selfless action to a lotus untouched by the water around it. Engagement need not become possessiveness.", "Care deeply without letting ego own the work.", "Help fully, then release the need to control how others respond."),
    story(60, "Action", "Skill in Action", "Krishna calls yoga skill in action: attention, balance and ethical purpose working together. Speed alone is not excellence.", "Good work joins competence with right intention.", "Slow down enough to do one important task correctly."),
    story(61, "Action", "Shared Welfare", "The wise continue to work for the wellbeing of the world, Krishna says, even when they have nothing personal to prove. Maturity becomes contribution.", "Growth is incomplete until it benefits others.", "Use one skill to help someone without reward."),
    story(62, "Action", "Release the Result", "After careful preparation, Arjuna still had to act without a guarantee. Krishna’s counsel turns uncertainty from an excuse into a field for courage.", "Peace follows wholehearted effort and released control.", "Finish your part, then stop repeatedly checking the outcome."),
    story(63, "Action", "Begin Where You Stand", "The Gita was not spoken after every doubt disappeared. It helped Arjuna see enough to take the next responsible action.", "Clarity often grows after a sincere beginning.", "Start the smallest reversible step toward a difficult decision."),

    story(64, "Wisdom", "Changing Garments", "Krishna compares the soul changing bodies to a person changing worn clothes. The image asks us to look beyond appearance and change.", "Your deepest dignity is not limited to outward form.", "Treat someone’s age, body or status without contempt."),
    story(65, "Wisdom", "Heat and Cold", "Krishna says heat, cold, pleasure and pain arrive and pass through contact with the world. Endurance remembers that a present feeling is not permanent.", "Do not make a permanent decision from a passing state.", "Wait until a strong emotion settles before deciding."),
    story(66, "Wisdom", "The Field and Its Knower", "The Gita calls body and mind a field and awareness its knower. Thoughts can be observed instead of automatically believed.", "Awareness creates space for choice.", "Say “I notice this thought” instead of “This thought is truth.”"),
    story(67, "Wisdom", "Three Kinds of Weather", "Sattva, rajas and tamas can be understood as clarity, restless drive and heaviness moving through the mind. They are patterns to notice, not labels for condemning people.", "Observe your state so you can choose what nourishes clarity.", "After one activity, note whether you feel clear, restless or dull."),
    story(68, "Wisdom", "The Upside-Down Tree", "Krishna describes an ancient tree with roots above and branches below. Visible habits are fed by hidden beliefs and attachments.", "Lasting change works at the root, not only the symptom.", "Write the hidden need beneath one repeating habit."),
    story(69, "Wisdom", "The Universal Form", "Arjuna asks to see Krishna’s universal form and is overwhelmed by vastness. The vision makes his personal viewpoint feel real but incomplete.", "Humility is knowing your view is not the whole.", "Ask what important perspective you may be missing."),
    story(70, "Wisdom", "Equal Vision", "Krishna describes the wise as seeing the same spiritual dignity across learned and humble, human and animal. Difference remains, but contempt loses its excuse.", "See difference without denying shared worth.", "Show equal courtesy to someone with less status or power."),
    story(71, "Wisdom", "The Lamp of Knowledge", "Krishna says knowledge can burn confusion as fire transforms fuel. Information becomes wisdom when it changes conduct.", "Learning is complete only when it guides action.", "Practise one principle you already understand."),
    story(72, "Wisdom", "Faith Reveals Its Motive", "The Gita examines faith through the qualities shaping it. A practice driven by clarity differs from one driven by display or confusion.", "The motive beneath a good act matters.", "Before helping, quietly name your true intention."),

    story(73, "Relationships", "Yashoda’s Loving Boundary", "Yashoda adored Krishna yet still corrected his mischief. Affection did not require pretending every action was acceptable.", "Love can be warm and firm at the same time.", "Set one boundary without withdrawing affection."),
    story(74, "Relationships", "The Parents Behind the Prison Door", "After Kamsa’s defeat, Krishna honoured Devaki and Vasudeva and recognised years of sacrifice. Freedom made room for gratitude.", "Remember those whose unseen sacrifices helped you grow.", "Thank a parent or elder for one specific act of care."),
    story(75, "Relationships", "Rukmini’s Message", "Rukmini clearly expressed her choice when powerful people planned her future without listening. Krishna took her voice seriously.", "Respect begins by hearing another person’s agency.", "Ask what support someone wants before deciding for them."),
    story(76, "Relationships", "Gandhari’s Grief", "After the war, Gandhari’s grief became anger toward Krishna. He did not turn her sorrow into a debate he needed to win.", "Sometimes compassion listens before it explains.", "Let someone describe pain without making the moment about you."),
    story(77, "Relationships", "Vidura’s Simple Welcome", "Krishna accepted Vidura’s humble hospitality with warmth. Respect did not rise or fall with the wealth of the host.", "Receive sincere care without measuring its display.", "Thank someone for the effort behind a simple offering."),
    story(78, "Relationships", "Kubja Is Seen", "Krishna met Kubja without reducing her to the appearance others noticed first. Recognition restored dignity before anything else changed.", "See the person before the label.", "Include someone who is usually overlooked."),
    story(79, "Relationships", "Balarama’s Different View", "Krishna and Balarama did not always approach events identically, yet difference did not erase their bond. Respect can survive disagreement.", "Closeness does not require identical opinions.", "Disagree with one idea without insulting the person."),
    story(80, "Relationships", "Arjuna Asks for Guidance", "Arjuna admitted that friendship alone could not resolve his confusion and asked Krishna to teach him. Their relationship changed roles without losing trust.", "Maturity knows when to ask a friend for honest guidance.", "Tell a trusted person where you need counsel, not only comfort."),
    story(81, "Relationships", "The Gopis Hear the Flute", "The flute drew attention away from routine toward love and presence. Devotion became the willingness to listen deeply.", "Relationships deepen when attention is wholehearted.", "Give someone five minutes without a screen or interruption."),

    story(82, "Youth", "The Mark on the Paper", "A student saw a low mark and thought, “I am a failure.” Remembering Krishna’s teaching on action, she reviewed her method and made a new study plan.", "A result can guide improvement without defining worth.", "Change one study habit instead of insulting yourself."),
    story(83, "Youth", "The Silent Group Chat", "A cruel joke about a classmate collected laughing emojis. One student paused, refused to forward it and privately checked on the person targeted.", "Digital courage is still courage.", "Do not like, share or remain silently involved in online cruelty."),
    story(84, "Youth", "The Empty Seat", "A new child ate alone while everyone waited for someone else to invite him. A girl remembered Krishna welcoming Sudama and moved her lunch beside the empty seat.", "Inclusion often begins with one person moving first.", "Invite someone who is alone to join you."),
    story(85, "Youth", "The Team List", "When his friend was selected and he was not, jealousy tightened a boy’s chest. He congratulated his friend, then asked the coach what he could improve.", "Another person’s success does not cancel your path.", "Offer one sincere congratulations and take one growth step."),
    story(86, "Youth", "The Argument at Home", "A teenager wanted to shout, “You never understand me.” She paused and said, “I feel unheard. Can I explain without interruption, then listen to you?”", "Clear needs travel farther than blame.", "Use one “I feel… I need… Would you…?” sentence."),
    story(87, "Youth", "The Wallet Near the Gate", "A student found money when nobody was watching. He handed it to the office because Dharma did not disappear when witnesses did.", "Integrity is who you are without an audience.", "Return or report something that is not yours."),
    story(88, "Youth", "The Elderly Neighbour’s Bag", "Everyone rushed past an elderly neighbour carrying groceries. A child remembered that service can be worship and offered safe help.", "Small service can carry great respect.", "Ask an elder whether one practical task would help."),
    story(89, "Youth", "The Injured Puppy", "Children gathered around an injured puppy, but one child stopped them from frightening it, called an adult and found appropriate help.", "Compassion acts carefully, not only emotionally.", "Learn the safe local way to help an injured animal."),
    story(90, "Youth", "The Sapling by the Wall", "A class planted a sapling for a photograph. One student kept watering it after the celebration was forgotten.", "Care becomes real through consistency.", "Choose one living thing to care for regularly."),

    story(91, "Discipline", "The Morning Promise", "A student set an early alarm for a grand new routine, then failed after two days. He chose a smaller promise he could repeat and built from there.", "Discipline grows through sustainable promises.", "Make one routine five minutes smaller and keep it."),
    story(92, "Discipline", "The Phone Outside the Room", "A girl blamed her mind for wandering while every notification called it away. She placed the phone outside and gave her attention a calmer home.", "Change the environment before condemning the mind.", "Move one distraction out of reach for twenty minutes."),
    story(93, "Discipline", "One Note at a Time", "A young musician wanted to play like Krishna’s flute without practising basic notes. Her teacher reminded her that beauty rests on patient repetition.", "Mastery hides inside ordinary practice.", "Repeat one basic skill slowly and correctly."),
    story(94, "Discipline", "The Promise Written Down", "A boy often said, “I forgot,” until he began writing promises and checking them each evening. His word became more dependable.", "Memory needs systems when trust depends on it.", "Record one commitment and set a reminder."),
    story(95, "Discipline", "The Honest Expense", "A young worker noticed extra money in a reimbursement. Returning it felt small, but it kept his wealth free from dishonesty.", "How money is earned matters as much as how much is earned.", "Correct one financial mistake in your favour."),
    story(96, "Discipline", "Rest Is Also a Duty", "A student studied until exhaustion and called it dedication. Remembering Krishna’s teaching on balance, she slept properly and learned with a clearer mind.", "Discipline includes wise rest, not self-punishment.", "Protect enough time for sleep tonight."),
    story(97, "Discipline", "The Specific Apology", "Instead of saying, “Sorry if you were hurt,” a friend named what he did, acknowledged the impact and changed the behaviour.", "Repair begins where excuses end.", "Make one apology without “if” or “but.”"),
    story(98, "Discipline", "Waiting Without Wasting", "A result was delayed, and a student refreshed the page all day. She chose to prepare for either outcome and used waiting as practice.", "Patience can remain active.", "Use ten waiting minutes for preparation or service."),
    story(99, "Discipline", "The Body as a Temple", "A boy wanted a strong mind while neglecting food, movement and sleep. He learned that caring for the body supports the duties carried through it.", "Health is stewardship, not vanity.", "Choose one nourishing action for your body today."),

    story(100, "Devotion", "The Leaf and the Heart", "A child had no costly offering and placed a clean leaf before Krishna with gratitude. The simplicity made room for sincerity.", "Devotion is measured by the heart, not the price.", "Offer one simple thing with complete attention."),
    story(101, "Devotion", "The Small Lamp", "One lamp could not remove every darkness in the world, but it could illuminate the space around it. The devotee lit it and began there.", "You do not need to solve everything to bring light somewhere.", "Improve one small space within your reach."),
    story(102, "Devotion", "The Long Temple Queue", "A visitor grew angry while waiting for darshan, then realised impatience was shaping the very heart brought to prayer. The queue became practice.", "The journey to worship is also part of worship.", "Use one delay to practise patience and courtesy."),
    story(103, "Devotion", "A Prayer Beyond Myself", "A girl began prayer with her own worries, then remembered friends, strangers, animals and the earth. Her heart felt larger than the fear she brought.", "Love grows when prayer overflows personal need.", "Include three others in your prayer today."),
    story(104, "Devotion", "Three Minutes of Silence", "A busy student believed meditation required an empty mind and a free hour. He offered three quiet minutes and simply returned whenever thoughts wandered.", "Sincere practice can begin small.", "Sit silently for three minutes without demanding perfection."),
    story(105, "Devotion", "The Unseen Service", "After a gathering, someone stayed to clean while others left. No applause followed, but the place became ready for everyone who came next.", "Service remains sacred when nobody notices.", "Do one useful task anonymously."),
    story(106, "Devotion", "The Gratitude List", "A difficult day seemed empty of goodness until a child named clean water, a meal and one kind voice. Gratitude did not deny pain; it prevented pain from hiding everything else.", "Gratitude widens the truth of a hard day.", "Write three specific things that supported you today."),
    story(107, "Devotion", "The Path with Your Name", "A seeker copied another person’s routine and felt constantly behind. Krishna’s teaching on one’s own Dharma helped her build a path suited to her duties and nature.", "A meaningful path need not look like someone else’s.", "Remove one comparison and choose your own next step."),
    story(108, "Devotion", "Love Without a Ledger", "A devotee kept count of every favour and disappointment until love became a transaction. He began giving freely while keeping wise boundaries.", "The highest love does not keep score, but it still respects dignity.", "Offer one caring action without demanding recognition." )
)

fun oneMinuteStory(id: String?): OneMinuteKrishnaStory =
    oneMinuteKrishnaStories.firstOrNull { it.id == id } ?: oneMinuteKrishnaStories.first()
